 "content": "def transform(grid):
    cells=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1]
    r0,r1=min(r for r,c in cells),max(r for r,c in cells)
    c0,c1=min(c for r,c in cells),max(c for r,c in cells)
    out=[[grid[r][c] for r in range(r0,r1+1)] for c in range(c0,c1+1)]
    # The outside key replaces the three marker colors on the rotated canvas;
    # output positions are the rotated, board-relative coordinates of each key.
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v not in (0,1) and not (r0<=r<=r1 and c0<=c<=c1):
                y,x=r-r0,c-c0
                oy=x
                ox=(r1-r0)-y
                if 0<=oy<len(out) and 0<=ox<len(out[0]): out[oy][ox]=v
    return out
